-- `(NULL, text)` with 2 685 characters is refused — a size the same text in a non-NULL
-- row would not reach. A NULL key is sized whatever the unique rule.
-- @setup
CREATE TABLE t (n text, a text);
CREATE INDEX t_i ON t (n, a);
-- @test
-- @expect-error: the null bitmap pushes the row over the limit
-- @expect-message
-- @profile-lock
INSERT INTO t VALUES (NULL, '');
